// Simple endless runner based on IDEA.md
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.offsetWidth);
  const H = (canvas.height = canvas.offsetHeight);
  const GROUND = H - 50;
  const PLAYER = {
    w: 30,
    h: 50,
    x: 80,
    y: GROUND - 50,
    vy: 0,
    jumpV: -12,
    gravity: 0.6,
    sliding: false,
    slideTimer: 0,
    slideDuration: 15,
    onGround() {return this.y >= GROUND - this.h;}
  };
  const obstacles = [];
  const orbs = [];
  let frame = 0, score = 0, gameOver = false;

  // Input handling: click/tap toggles jump or slide
  canvas.addEventListener('pointerdown', () => {
    if (gameOver) return reset();
    if (PLAYER.onGround()) {
      PLAYER.vy = PLAYER.jumpV;
    } else if (!PLAYER.sliding) {
      PLAYER.sliding = true;
      PLAYER.slideTimer = PLAYER.slideDuration;
      PLAYER.h = 30; // shorter height while sliding
    }
  });

  function reset() {
    obstacles.length = 0;
    orbs.length = 0;
    PLAYER.y = GROUND - 50;
    PLAYER.vy = 0;
    PLAYER.h = 50;
    PLAYER.sliding = false;
    frame = 0;
    score = 0;
    gameOver = false;
    loop();
  }

  function spawnObstacle() {
    const w = 20 + Math.random() * 30;
    const h = 30 + Math.random() * 40;
    obstacles.push({x: W + w, y: GROUND - h, w, h});
  }

  function spawnOrb() {
    const r = 8;
    const y = GROUND - 80 - Math.random() * 100;
    orbs.push({x: W + r, y, r});
  }

  function update() {
    frame++;
    // Player physics
    PLAYER.vy += PLAYER.gravity;
    PLAYER.y += PLAYER.vy;
    if (PLAYER.y > GROUND - PLAYER.h) {
      PLAYER.y = GROUND - PLAYER.h;
      PLAYER.vy = 0;
    }
    if (PLAYER.sliding) {
      PLAYER.slideTimer--;
      if (PLAYER.slideTimer <= 0) {
        PLAYER.sliding = false;
        PLAYER.h = 50;
      }
    }
    // Move obstacles & orbs
    obstacles.forEach(o => o.x -= 4);
    orbs.forEach(o => o.x -= 4);
    // Remove off‑screen
    while (obstacles.length && obstacles[0].x + obstacles[0].w < 0) obstacles.shift();
    while (orbs.length && orbs[0].x + orbs[0].r < 0) orbs.shift();
    // Spawn logic
    if (frame % 120 === 0) spawnObstacle();
    if (frame % 200 === 0) spawnOrb();
    // Collision detection
    for (const o of obstacles) {
      if (PLAYER.x < o.x + o.w && PLAYER.x + PLAYER.w > o.x &&
          PLAYER.y < o.y + o.h && PLAYER.y + PLAYER.h > o.y) {
        gameOver = true;
      }
    }
    for (let i = orbs.length - 1; i >= 0; i--) {
      const o = orbs[i];
      const dx = (PLAYER.x + PLAYER.w/2) - o.x;
      const dy = (PLAYER.y + PLAYER.h/2) - o.y;
      if (Math.hypot(dx, dy) < o.r + Math.min(PLAYER.w, PLAYER.h)/2) {
        score += 10;
        orbs.splice(i, 1);
      }
    }
    // Falling off ground (gap) – simplified as y > GROUND
    if (PLAYER.y > GROUND) gameOver = true;
    if (!gameOver) score++;
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // Ground
    ctx.fillStyle = '#444';
    ctx.fillRect(0, GROUND, W, H - GROUND);
    // Player silhouette
    ctx.fillStyle = '#fff';
    ctx.fillRect(PLAYER.x, PLAYER.y, PLAYER.w, PLAYER.h);
    // Obstacles
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // Orbs
    ctx.fillStyle = '#0f0';
    orbs.forEach(o => {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.r, 0, Math.PI*2);
      ctx.fill();
    });
    // Score / Game Over
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over - Click to Restart', W/2, H/2);
    }
  }

  function loop() {
    if (!gameOver) update();
    draw();
    requestAnimationFrame(loop);
  }
  // expose for debugging
  window.gameReset = reset;
  loop();
})();
